{
  "triage": "self_observe",
  "department": "呼吸内科",
  "conditions": [
    {
      "name": "急性上呼吸道感染（病毒性，轻型）",
      "evidence_idx": [2],
      "quote": "有临床症状者主要表现为中低度发热、咽干、咽痛、鼻 塞、流涕等上呼吸道感染症状。"
    },
    {
      "name": "新型冠状病毒感染（轻型或无症状型）",
      "evidence_idx": [2],
      "quote": "部分患者可以鼻塞、 流涕、咽痛、嗅觉味觉减退或丧失、结膜炎、肌痛和腹泻等"
    },
    {
      "name": "百日咳卡他期（以流涕、喷嚏起病）",
      "evidence_idx": [0],
      "quote": "表现为流涕、打喷嚏、流泪、咽痛、阵发性咳嗽等上呼 吸道感染症状。"
    },
    {
      "name": "成人百日咳（不典型阵发性咳嗽）",
      "evidence_idx": [0],
      "quote": "青少年或成人百日咳患者，常无典型痉咳，表现为阵发 性咳嗽和暂时性缓解交替。"
    }
  ],
  "preparation": "就诊前记录：症状从哪天开始（现为第3天）、流涕是清水样还是黄脓样、有无鼻塞/咽痛/发热（每天测体温并记下数值）、有无咳嗽及咳嗽性质（是否成串阵咳、夜间是否加重、咳后有无呕吐或吼声）、有无嗅觉味觉减退、有无腹泻或眼红、近期是否接触过发热咳嗽的人或活禽、有无基础病与正在服用的药物。向医生按时间顺序描述，不要自行判断为“感冒”。以下情况立刻就医：出现发热且体温持续升高、气促或呼吸困难、胸痛、咳血痰、嘴唇发紫、精神明显变差；流涕超过10天不缓解或反而加重、出现阵发性剧烈咳嗽影响睡眠或咳后呕吐；婴幼儿、老人、孕妇或有慢性心肺疾病者症状加重应尽早就诊。以上不构成诊断，仅为就诊参考。"}

{
  "triage": "self_observe",
  "department": "呼吸内科",
  "conditions": [
    {
      "name": "其他急性呼吸道病毒感染（含新型冠状病毒感染）",
      "evidence_idx": [4],
      "quote": "部分患者可以鼻塞、流涕、咽痛、嗅觉味觉减退或丧失、结膜炎、肌痛和腹泻等为主要表现"
    },
    {
      "name": "上呼吸道感染早期（咽干、咽痛、鼻塞、流涕为主）",
      "evidence_idx": [1],
      "quote": "部分患者可伴有肌肉酸痛、嗅觉味觉减退或丧失、鼻塞、流涕、腹泻、结膜炎等"
    },
    {
      "name": "百日咳（早期以流涕、打喷嚏等上呼吸道症状起病）",
      "evidence_idx": [0],
      "quote": "表现为流涕、打喷嚏、流泪、咽痛、阵发性咳嗽"
    }
  ],
  "preparation": "【就诊前可先自我观察】单纯流鼻涕三天、无发热和呼吸困难，多属上呼吸道感染的常见表现，可先在家观察并记录症状变化，注意休息、适量饮水、戴口罩、勤洗手。【需要向医生描述的内容】①流鼻涕从哪天开始、是清水样还是黄稠、单侧还是双侧；②有无发热（每天测体温并记录最高值）、咽痛、咳嗽、打喷嚏、流泪；③嗅觉、味觉有无减退或丧失；④有无肌肉酸痛、腹泻、眼睛红；⑤周围有无类似症状的人、近期有无聚集或旅行史；⑥已自行用过什么处理、效果如何。【就诊时建议携带】体温记录、症状时间线、既往病史与正在服用的药物清单。【出现以下情况请立刻就医或挂急诊】持续高热不退或热退后再次加重；出现呼吸困难、气促、胸闷胸痛、口唇发紫；精神反应差、嗜睡或抽搐；剧烈头痛、频繁呕吐、明显出血倾向；婴幼儿出现呼吸暂停、发绀、拒奶；症状超过一周仍不缓解或明显加重。以上判断基于《参考片段》，不构成诊断，具体以医生面诊为准。"
}

{
  "triage": "emergency",
  "department": "急诊科",
  "conditions": [
    {
      "name": "鼻咽纤维血管瘤等鼻腔、鼻咽部血管性病变（反复大量鼻出血）",
      "evidence_idx": [1],
      "quote": "此病好发于青少年男性，表现为反复大量鼻出血。"
    },
    {
      "name": "鼻咽癌等鼻咽部肿瘤（需排除）",
      "evidence_idx": [2],
      "quote": "儿童及青少年鼻咽癌与成人鼻咽癌表现基本一致"
    },
    {
      "name": "凝血功能异常导致的出血不易停止",
      "evidence_idx": [4],
      "quote": "了解患儿有无凝血功能异常"
    },
    {
      "name": "鼻咽部新生物或黏膜病变（需鼻内镜直视检查明确）",
      "evidence_idx": [2],
      "quote": "能进入鼻腔全面仔细地观察鼻咽部病变"
    },
    {
      "name": "腺样体增生等鼻咽部良性增生（儿童青少年常见）",
      "evidence_idx": [1],
      "quote": "儿童期腺样体增生比较常见"
    }
  ],
  "preparation": "先分清流出的是血还是清水样鼻涕：若是血且连续三天不停，属于需要尽快止血和查因的情况，请直接去急诊；若只是清水样鼻涕、无血，多为上呼吸道感染，可改挂呼吸内科或全科医学科门诊。就诊前准备：①记录出血开始时间、持续天数、是单侧还是双侧、出血量（几口/几张纸/有无血块）、颜色、能否自行停止；②有无鼻塞、听力下降、耳闷、颈部或耳后摸到肿块、发热、皮肤皮疹、牙龈或其他部位出血；③近期是否服用阿司匹林、华法林等抗凝药，有无肝病、血液病史及家族肿瘤史；④带上既往血常规、凝血功能、鼻内镜或影像报告。向医生这样描述：“鼻子流血（或流液）已三天，量大约多少，按压后能否止住，有没有头晕、心慌、乏力”。途中可坐位、头稍前倾、手指捏紧鼻翼软部持续按压10分钟，不要仰头，不要填塞不洁纸巾。出现下列情况立即就医（呼叫急救）：出血量大且按压20分钟仍不止、口中有血或呕血、面色苍白出冷汗、头晕心慌站不稳、呼吸困难、意识改变。以上均不构成诊断，最终以医生面诊为准。"
}

